<template><section class="social-page utility-page"><header class="utility-header"><button aria-label="뒤로" @click="router.back()">‹</button><h1>알림</h1><button :disabled="busy||!items.some(n=>!n.seen)" @click="readAll">모두 읽음</button></header><RouterLink to="/settings" class="notification-settings">알림 종류·방해금지 설정 ›</RouterLink><div class="push-setting"><div><strong>푸시 알림</strong><p>새 메시지와 중요한 소식을 받아요.</p></div><button :disabled="busy" @click="toggle">{{pushOn?'끄기':'켜기'}}</button></div><p v-if="error" role="alert">{{error}}</p><p v-if="status" role="status">{{status}}</p><p v-if="!items.length" class="social-empty">{{loading?'불러오는 중…':'새로운 소식이 생기면 여기에 모아드릴게요.'}}</p><button v-for="n in items" :key="n.id" :class="['notice-row',{unseen:!n.seen}]" @click="open(n)"><span class="notice-dot"/><div><strong>{{n.title}}</strong><p>{{n.body}}</p><time>{{new Date(n.createdAt).toLocaleString('ko-KR')}}</time></div></button><button v-if="more" :disabled="loading" @click="load(true)">이전 알림 더 보기</button></section></template>
<script setup>import {ref,onMounted,onUnmounted} from 'vue';import {useRouter} from 'vue-router';import api from '../../api/api';import {enablePush,disablePush,hasPush} from '../../components/push';import {refreshBadges} from '../../components/notificationEvents';import '../../components/social.css';const router=useRouter(),items=ref([]),error=ref(''),status=ref(''),busy=ref(false),loading=ref(false),more=ref(false),pushOn=ref(false);let timer,disposed=false;
async function load(older=false){if(loading.value)return;loading.value=true;try{const {data}=await api.get('/social/inbox',{params:older?{before:items.value.at(-1)?.id}:{}});if(disposed)return;const combined=new Map((older?items.value:[]).map(n=>[n.id,n]));data.forEach(n=>combined.set(n.id,n));items.value=[...combined.values()];more.value=data.length===50;error.value='';}catch{error.value='알림을 불러오지 못했어요.';}finally{loading.value=false;}}
async function open(n){try{await api.post('/social/inbox/read',[n.id]);n.seen=true;refreshBadges();router.push(n.link);}catch{error.value='알림을 열지 못했어요.';}}
async function readAll(){busy.value=true;try{await api.post('/social/inbox/read',items.value.filter(n=>!n.seen).map(n=>n.id).slice(0,200));await load();refreshBadges();}catch{error.value='읽음 처리에 실패했어요.';}finally{busy.value=false;}}
async function toggle(){busy.value=true;error.value='';try{if(pushOn.value){await disablePush();pushOn.value=false;status.value='이 기기의 푸시 알림을 껐어요.';}else{await enablePush();pushOn.value=true;status.value='푸시 알림을 켰어요.';}}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(async()=>{load();pushOn.value=await hasPush();timer=setInterval(()=>{if(!document.hidden&&items.value.length<=50)load();},10000);});onUnmounted(()=>{disposed=true;clearInterval(timer);});</script>
<style scoped>.push-setting{display:flex;align-items:center;justify-content:space-between;background:#f9f5f2;padding:16px;border-radius:16px;margin-bottom:20px}.push-setting strong{font-size:14px}.push-setting p{font-size:11px;color:#8f8178;margin:6px 0}.social-page .notice-row{display:flex;width:100%;text-align:left;background:transparent;border-radius:0;padding:20px 4px;border-bottom:1px solid #f0eae6;gap:10px;color:#302925}.notice-row strong{font-size:14px}.notice-row p{font-size:12px;line-height:1.7;color:#8f8178;margin:6px 0}.notice-row time{font-size:10px;color:#aaa}.notice-dot{width:6px;height:6px;flex:none;margin-top:6px;border-radius:50%}.unseen .notice-dot{background:#d65243}.notice-row.unseen{background:#fff9f5}.notification-settings{display:block;text-align:right;font-size:12px;color:#986b55;margin-bottom:16px;text-decoration:none}</style>
